join public.events e on e.id = x->>0
on conflict (event_id, user_id) do nothing;

with want as (
  select x.key as event_id, (x.value->>'confirmed')::int c, (x.value->>'waitlisted')::int w, (x.value->>'checked_in')::int k
  from jsonb_each('{"e_speranza":{"confirmed":25,"waitlisted":0,"checked_in":175},"e_open_mic":{"confirmed":64,"waitlisted":0,"checked_in":0},"e_battle_bands":{"confirmed":224,"waitlisted":0,"checked_in":0},"e_street_play":{"confirmed":53,"waitlisted":0,"checked_in":97},"e_quiz":{"confirmed":45,"waitlisted":0,"checked_in":0},"e_movie":{"confirmed":80,"waitlisted":0,"checked_in":0},"e_standup":{"confirmed":117,"waitlisted":0,"checked_in":0},"e_dj_night":{"confirmed":186,"waitlisted":0,"checked_in":0},"e_fashion":{"confirmed":140,"waitlisted":0,"checked_in":0},"e_classical":{"confirmed":74,"waitlisted":0,"checked_in":0},"e_dance_faceoff":{"confirmed":110,"waitlisted":0,"checked_in":0},"e_arduino":{"confirmed":37,"waitlisted":0,"checked_in":0},"e_hiphop":{"confirmed":60,"waitlisted":6,"checked_in":0},"e_edc_talk":{"confirmed":101,"waitlisted":0,"checked_in":0},"e_fin_lecture":{"confirmed":40,"waitlisted":0,"checked_in":0},"e_trials":{"confirmed":30,"waitlisted":0,"checked_in":0},"e_blood":{"confirmed":72,"waitlisted":0,"checked_in":0},"e_andha_yug":{"confirmed":95,"waitlisted":0,"checked_in":0},"e_hacking":{"confirmed":6,"waitlisted":0,"checked_in":0},"e_writing":{"confirmed":22,"waitlisted":0,"checked_in":0},"e_caic_showcase":{"confirmed":50,"waitlisted":0,"checked_in":0},"e_nss_teach":{"confirmed":18,"waitlisted":0,"checked_in":0},"e_bnc_talk":{"confirmed":30,"waitlisted":0,"checked_in":0},"e_open_source":{"confirmed":20,"waitlisted":0,"checked_in":0},"e_becon_pass":{"confirmed":18,"waitlisted":0,"checked_in":0},"e_rdv_pronite":{"confirmed":12,"waitlisted":0,"checked_in":0}}'::jsonb) x
), pool as (
  select w.event_id, p.id user_id, row_number() over (partition by w.event_id order by md5(w.event_id || p.id::text)) n, w.c, w.w, w.k
  from want w join public.events e on e.id = w.event_id
  join public.profiles p on (p.is_iitd or e.eligibility = 'open')
  where p.id not in ('19a780ab-5eb8-23df-f260-8be7eb4dc186', '44dfa18f-10eb-a428-1f3f-b3f2784141c4', '94acb1ff-999a-733d-10ab-c77456d2f732', '2a0853c1-bef6-8740-a3e0-6677c1b30fdc', 'a80b9579-262f-9327-06ba-a09894fcdc97')
    and not exists (select 1 from public.registrations r where r.event_id = w.event_id and r.user_id = p.id)
)
insert into public.registrations (event_id, user_id, status, qr_token, amount_due, paid_at, created_at, checked_in_at)
select pool.event_id, pool.user_id,
  case when n <= k then 'checked_in' when n <= k + c then 'confirmed' else 'waitlisted' end,
  public.new_pass_code(), e.price,
  case when n <= k and e.price > 0 then least(now(), e.starts_at) + interval '5 minutes' end,
  now() - make_interval(mins => (abs(hashtext(pool.event_id || pool.user_id::text)) % 14000) + 60),
  case when n <= k then least(now(), e.starts_at) + make_interval(mins => (abs(hashtext(pool.user_id::text)) % 50)) end
from pool join public.events e on e.id = pool.event_id
where n <= k + c + w;

insert into public.event_staff (event_id, user_id, added_by)
select e.id, 'a80b9579-262f-9327-06ba-a09894fcdc97', '2a0853c1-bef6-8740-a3e0-6677c1b30fdc' from public.events e
where e.reg_mode = 'platform' and (e.fest_id = 'f_demo' or e.sample_day between 0 and 1)
on conflict do nothing;

select public.roll_sample_dates();

select set_config('iitdlive.trusted', '', false);
